$$
\begin{array}{r l} f ^ {(n)} (x) & = \sum_ {i = 0} ^ {n} C _ {n} ^ {i} \left(\frac {1}{x}\right) ^ {(i)} (\sin x) ^ {(n - i)} = \sum_ {i = 0} ^ {n} C _ {n} ^ {i} (- 1) ^ {i} \frac {i !}{x ^ {i + 1}} \sin \left[ x + (n - i) \frac {\pi}{2} \right] \\ & = \sum_ {i = 0} ^ {n} C _ {n} ^ {i} (- 1) ^ {i} \frac {i !}{x ^ {i + 1}} \left[ \cos \frac {(n - i) \pi}{2} \cdot \sin x + \sin \frac {(n - i) \pi}{2} \cdot \cos x \right] \\ & = (- 1) ^ {n} \frac {n !}{x ^ {n + 1}} \left\{\left[ \sum_ {i = 0} ^ {n} (- 1) ^ {n - i} \frac {1}{(n - i) !} \sin \frac {(n - i) \pi}{2} \cdot x ^ {n - i} \right] \cos x + \left[ \sum_ {i = 0} ^ {n} (- 1) ^ {n - i} \frac {1}{(n - i) !} \cos \frac {(n - i) \pi}{2} \cdot x ^ {n - i} \right] \sin x \right\}. \end{array}
$$

$$
\begin{array}{l}\lim _ {n \rightarrow \infty} p _ {n} (x) = \sum_ {k = 0} ^ {\infty} (- 1) ^ {k} \frac {1}{k !} \sin \frac {k \pi}{2} \cdot x ^ {k} = - \sum_ {n = 0} ^ {\infty} (- 1) ^ {n} \frac {1}{(2 n + 1) !} \cdot x ^ {2 n + 1} = - \sin x,\\\lim _ {n \rightarrow \infty} q _ {n} (x) = \sum_ {k = 0} ^ {\infty} (- 1) ^ {k} \frac {1}{k !} \cos \frac {k \pi}{2} \cdot x ^ {k} = \sum_ {n = 0} ^ {\infty} (- 1) ^ {n} \frac {1}{(2 n) !} x ^ {2 n} = \cos x.\end{array}
$$
